          "point": "考期：0610、1910简答题 · (1)概念:公司合并是指两个或两个以上的公司依法达成合意归并为一个公司的法律行为。(2)分类:公司合并可以采取吸收合并或新设合并两种方式。(3)法律后果:公司合并必然导致合并一方或双方公司的解散,被解散的公司的全部权利和义务由存续公司或新设公司承受。"
