          "point": "考期：1710简答题 · (1)法律地位不同:股份持有人与公司之间是财产关系、经营管理关系;而债券持有人与公司债权债务关系。(2)权利内容不同:股份持有人享有财产权、经营决策权;债券持有人享有按期收回本息权。(3)获得权利的对价形式不同:股份持有人可以用货币、法律允许的实物、知识产权、土地使用权等出资获得股权;债券持有人仅限于金钱给付。(4)持有物发行时间上的差异:股票在成立先后发行均可;债券只能在公司成立后发行。"
