          "freq": true,
          "title": "股份有限公司境外买壳上市和造壳上市的含义并分析其利弊",
          "point": "考期：1001、2010论述题 · (1)买壳上市是指境内企业直接收购一家已在海外证券市场挂牌上市的公司的部分或全部股权,取得对该境外上市公司的控制地位,然后对其注入资产,达到境内企业在海外间接上市的目的。(2)造壳上市是指国内企业到境外设立公司,由该境外公司以收购、股权置换等方式对境内公司形成控股关系,然后将该境外公司在境外交易所上市。(3)买壳上市实际上是上市公司国际并购的一种形式,其最大的优点就是方便、快捷,能在很短的时间实现企业上市的目的。但其缺点也是明显的,如可供选择的境外上市公司壳资源非常有限,收购的代价高昂,失败风险很大。(4)与买壳上市相比,造壳上市的成本和风险都相对较低,但缺点是从公司的设立到上市,其经过的时间相对较长。(5)买壳上市和造壳上市虽然形式不同,但本质上都是将国内资产通过境外壳公司实现在国际资本市场上筹资的目的。与直接上市相比,间接上市的好处是可以避开国内有关法律的限制和复杂的审批程序,又可以避开股市所在地法律对外来公司严格的条件限制,因而上市成本较低,花费的时间较短。此外,在境外注册的公司适用外国的会计和审计标准,容易获得境外证券市场的认可。"
