          "point": "考期：1610论述 · 口诀：转西北锤精火［1610论述］ · (1)长征是一部伟大的革命英雄主义的史诗。是中国革命转危为安的关键。(2)通过长征中国革命的大本营放在了；西北,为迎接中国人民抗日救亡的新高潮准备了条件。(3)保存并锤炼了中国革命的骨干力量；,这是党和红军极为宝贵的精华。(4)播撒了革命的火种；。(5)中国共产党人和红军将士用生命和热血铸就了伟大的长征精神。"
