          "point": "考期：1401选择、1107选择、2104选择 · 20世纪上半期,较为重要的垄断组织形式有:卡特尔、辛迪加、托拉斯、康采恩。(1)卡特尔,即通过生产或经营同类产品的一些大型垄断企业之间较稳定的垄断协议形成的、在生产或流通的某个或某些环节实行垄断的组织形式。(2)辛迪加,即把一些在法律上和生产上是独立的大垄断企业在流通环节上统一起来,进行垄断经营的组织形式。(3)托拉斯,即垄断了某种商品生产和经营全过程的独立的大型垄断企业。(4)康采恩,即由一两个特大型垄断企业为核心,联合了各方面各领域一大批企业所形成的超大型垄断集团。"
