          "point": "1.唯物辩证法与形而上学根本对立和斗争的焦点在于:是否承认矛盾是事物发展的动力。2.唯物辩证法的实质与核心,宇宙的根本规律是:(对立统一规律)；3.最根本的认识方法:(矛盾分析法)；4.对立统一规律揭示了事物发展的动力和源泉。质量互变规律揭示了事物发展的状态和形式。否定之否定规律揭示了事物发展的趋势和道路。质量互变规1.量变:没有根本性变化,事物数量增减和场所的变更,及事物构成成分在空间上排列组合的变化。"
