          "point": "3.(1)章炳麟《驳康有为论革命书》、邹容《革命军》、陈天华《警世钟》《猛回头》。(2)第一个全国性的资产阶级性质的政党中国同盟会；(1905年),标志中国资产阶级民主革命；进入一个新阶段。机关报是《民报》；,纲领:驱除鞑虏,恢复中华,创立民国,平均地权。4.(1)1911年黄兴领导黄花岗起义(广州起义)；(2)保路运动"
