          "point": "1.社会形态的分类:(1)根据生产关系的不同性质分:原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会(2)根据人的发展状况分:人的依赖性社会、物的依赖性社会、个人全面发展的社会三种；(3)技术社会形态分:渔猎社会、农业社会、工业社会、信息社会。2.(1)社会历史发展的决定性:指历史决定论,(2)社会历史发展的选择性:是指主体选择的作用。(3)既承认社会发展的客观规律,又承认主体选择的作用,这种观点属于历史唯物主义观点。"
