          "point": "(1)外国公司的分支机构应当在其名称中标明该外国公司的国籍及责任形式。(2)外国公司必须指定在中国境内负责该分支机构的代表人或者代理人。(3)外国公司必须向分支机构拨付与其所从事的经营活动相适应的资金。(4)外国公司的分支机构应当在本机构中置备该外国公司章程。"
