          "point": "重整界限是指启动重整程序的事由,即人⺠法院裁定债务人进行重整的法定依据或客观标准。重整界限为:企业法人不能清偿到期债务,并且资产不足以清偿全部债务或者明显缺乏清偿能力;或者企业法人有明显丧失清偿能力可能的情形。(1)具有破产原因或有破产原因之虞;(2)具有恢复生产的可能;(3)继续经营,逐步偿还债务,使债权人利益最大化"
