          "freq": false,
          "title": "公司原则上不得成为自己的股东的原因",
          "point": "(1)公司认购本公司的股份,会导致公司资本的减少,并可能导致上市公司借此操纵公司股票价格,损害公司中小股东的利益。(2)公司自为股东,导致公司同时具备了“公司”与“股东”的双重身份,致使权利义务关系不清。"
