          "point": "马克思主义作为无产阶级和人类解放的科学,是包括马克思主义哲学、马克思主义政治经济学和科学社会主义在内的统一整体。(1)马克思主义哲学——德国古典哲学——黑格尔和费尔巴哈——辩证法和唯物主义；(2)政治经济学——英国古典政治经济学——亚当·斯密和大卫·李嘉图——劳动价值论；(3)科学社会主义——英法两国空想社会主义——圣西门、傅里叶和欧文——空想社会主义学说"
