          "point": "(1)毛泽东在《关于正确处理人民内部矛盾的问题》中提出社会主义社会存在着敌我矛盾和人民内部矛盾两类性质根本不同的矛盾。(2)前者需要用强制的、专政的方法去解决,后者只能用民主的、说服教育的、“团结——批评——团结”的方法；去解决。(3)这一学；说创造性地阐述了社会主义矛盾学说；,是对科学社会主义的重要发展,对中国社会主义事业；具有长远的指导意义。"
