          "point": "(1)四项基本原则:坚持社会主义道路；,坚持人民民主专政,坚持共产党的领导,坚持马；克思列宁主义、毛泽东思想。(2)重要性:实现四个现代化的根本前提。如果动摇了其中的任何一项,那就动摇了整个社会主义现代化建设事业。7.中共十二届六中全会提出的我国社会主义精神文明建设的根本任务是什么?(简答题)(1)培养有理想、有道德、有文化、有纪律的社会主义公民；。(2)提高整个中华民族的思想道德素质和科学文化素质；。"
