          "point": "(1)党的十九大提出了“明确坚持和发展中国特色社会主义,总任务是实现社会主义现代化和中华民族伟大复兴,在全面建成小康社会的基础上,分两步走,在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国”等“八个明确；”,这是支撑习近平新时代中国特；色社会主义思想的四梁八柱;(2)大会提出了新时代坚持和发展中国特色社会主义的基本方略,即“坚持党对一切工作的领导”等“十四个坚持；”,这是实现总任务的“路线图”；和“方法论”。(3)“八个明确”和“十四个坚持”有机融合、有机统一,是习近平新时代中国特色社会主义思想的核心内容。"
